import { Color, Graphics } from 'cc';

// Cocos adaptation of animal-island-vue's design tokens, Card, Button and Title.
// Source and MIT notice: art/references/animal-island-ui.md / THIRD_PARTY_NOTICES.md.
export const ISLAND = {
    ink:'#624729', muted:'#74634D', paper:'#F8F8F0', card:'#F7F3DF',
    background:'#F0E8D8', border:'#D4C4A8', shadow:'#BDAEA0',
    primary:'#19C8B9', primaryDark:'#50B9AB', mint:'#E8FAF5',
    teal:'#82D5BB', tealBack:'#40A880', tealFold:'#186048',
    yellow:'#F7CD67', pink:'#F8A6B2', blue:'#889DF0',
} as const;

function rect(g:Graphics,x:number,y:number,w:number,h:number,r:number,fill:string){
    g.fillColor=new Color(fill);g.roundRect(x-w/2,y-h/2,w,h,r);g.fill();
}
export function islandPanel(g:Graphics,x:number,y:number,w:number,h:number,fill:string=ISLAND.card,pattern=false){
    rect(g,x,y-5,w,h,32,ISLAND.shadow);
    rect(g,x,y,w,h,32,fill);
    g.strokeColor=new Color(ISLAND.border);g.lineWidth=2;
    g.roundRect(x-w/2+1,y-h/2+1,w-2,h-2,31);g.stroke();
    if(pattern){
        g.fillColor=new Color(196,184,158,38);
        for(let py=y-h/2+24;py<y+h/2-20;py+=28)
            for(let px=x-w/2+24;px<x+w/2-20;px+=28)g.circle(px,py,1.5);
        g.fill();
    }
}
export function islandRibbon(g:Graphics,x:number,y:number,w:number,h:number){
    const half=w/2, tail=h*.42, drop=h*.2;
    for(const side of [-1,1]){
        g.fillColor=new Color(ISLAND.tealBack);
        g.moveTo(x+side*(half-tail),y+h/2-drop);
        g.lineTo(x+side*(half+tail),y+h/2-drop);
        g.lineTo(x+side*(half+tail*.55),y-drop);
        g.lineTo(x+side*(half+tail),y-h/2-drop);
        g.lineTo(x+side*(half-tail),y-h/2-drop);g.close();g.fill();
        g.fillColor=new Color(ISLAND.tealFold);
        g.moveTo(x+side*half,y-h/2+1);g.lineTo(x+side*(half-tail),y-h/2-drop);
        g.lineTo(x+side*(half-tail),y-h/2+1);g.close();g.fill();
    }
    rect(g,x,y-3,w,h,10,ISLAND.tealBack);
    rect(g,x,y,w,h,10,ISLAND.teal);
}
export function islandBackground(g:Graphics, green=false, width=750, height=1500){
    // Background.vue: exact default / dots-dark-green double-layer wallpaper.
    rect(g,0,0,width,height,0,green?'#BFE3BF':'#F7F3DF');
    g.fillColor=green?new Color(90,160,90,56):new Color(196,184,158,38);
    for(let y=-height/2;y<=height/2;y+=56)for(let x=-width/2;x<=width/2;x+=56)g.circle(x,y,3);
    g.fill();
    g.fillColor=green?new Color(140,200,140,38):new Color(196,184,158,26);
    for(let y=-height/2+14;y<=height/2;y+=28)for(let x=-width/2+14;x<=width/2;x+=28)g.circle(x,y,2);
    g.fill();
}

