export function islandModal(g:Graphics,w:number,h:number){
    for(const offset of [-7,0]){
        g.fillColor=new Color(offset?ISLAND.shadow:ISLAND.card);
        MODAL_OUTLINE.forEach(([x,y],i)=>{
            const px=(x-.5)*w,py=(.5-y)*h+offset;
            if(i===0)g.moveTo(px,py);else g.lineTo(px,py);
        });g.close();g.fill();
    }
}
